    // one object, and outside every block.
    const itemKeyOf = (scopePath, blockPath) => {
        const prefix = String(blockPath || '') + '.';
        const path = String(scopePath || '');
        return blockPath && path.startsWith(prefix) ? path.slice(prefix.length) : undefined;
    };

